import { useReducer } from 'react';

type State = { count: number };

type Action =
  | { type: 'increment'; payload?: number }
  | { type: 'decrement'; payload?: number }
  | { type: 'reset' };

function counterReducer(state: State, action: Action): State {
  switch (action.type) {
    case 'increment':
      return { count: state.count + (action.payload ?? 1) };
    case 'decrement':
      return { count: state.count - (action.payload ?? 1) };
    case 'reset':
      return { count: 0 };
    default:
      return state;
  }
}

function Counter() {
  const [state, dispatch] = useReducer(counterReducer, { count: 0 });

  return (
    <div className="flex items-center gap-4">
      <button onClick={() => dispatch({ type: 'decrement' })}>-</button>
      <span>{state.count}</span>
      <button onClick={() => dispatch({ type: 'increment', payload: 5 })}>+5</button>
      <button onClick={() => dispatch({ type: 'reset' })}>Reset</button>
    </div>
  );
}

import { useReducer } from 'react';

type ToggleState = { on: boolean };

interface ToggleAction {
  type: 'TOGGLE' | 'SET' | 'RESET';
  payload?: { value: boolean };
}

function createToggleReducer(initial = false) {
  return function toggleReducer(state: ToggleState, action: ToggleAction): ToggleState {
    switch (action.type) {
      case 'TOGGLE':
        return { on: !state.on };
      case 'SET':
        return { on: action.payload!.value };
      case 'RESET':
        return { on: initial };
      default:
        return state;
    }
  };
}

function useToggle(initial = false) {
  const reducer = createToggleReducer(initial);
  const [state, dispatch] = useReducer(reducer, { on: initial });

  const toggle = () => dispatch({ type: 'TOGGLE' });
  const set = (value: boolean) => dispatch({ type: 'SET', payload: { value } });
  const reset = () => dispatch({ type: 'RESET' });

  return { ...state, toggle, set, reset };
}
